class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2021, 1, 1)
        self.SetEndDate(2023, 12, 31)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.bucket_start = None
        self.bucket_values = []

    def OnData(self, slice: Slice):
        self.current_slice = slice
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(current_date)

        if self.held_option is not None and self.entry_price is not None:
            self._evaluate_profit_target(slice)

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._process_minute_bar(bar)

    def _process_minute_bar(self, bar: TradeBar):
        bar_time = bar.Time
        bar_date = bar_time.date()
        session_start = datetime(bar_date.year, bar_date.month, bar_date.day, 9, 30)
        session_end = datetime(bar_date.year, bar_date.month, bar_date.day, 16, 0)

        if bar_time < session_start or bar_time >= session_end:
            return

        minutes_from_open = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._complete_five_minute_bar()
            self.bucket_start = bucket_start
            self.bucket_values = []

        self.bucket_values.append(bar)

        if len(self.bucket_values) == 5:
            self._complete_five_minute_bar()
            self.bucket_start = None
            self.bucket_values = []

    def _complete_five_minute_bar(self):
        if self.bucket_start is None or len(self.bucket_values) != 5:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        actual_times = [bar.Time for bar in self.bucket_values]
        if actual_times != expected_times:
            return

        close_time = self.bucket_start + timedelta(minutes=5)
        if close_time.time() < time(9, 35):
            return

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        close = self.bucket_values[-1].Close
        point = IndicatorDataPoint(self.spy, close_time, close)

        self.fast.Update(point)
        self.slow.Update(point)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        close_clock = close_time.time()
        if not (time(9, 45) <= close_clock <= time(14, 30)):
            return

        if bullish_cross:
            self._attempt_entry()

    def _attempt_entry(self):
        if self.current_slice is None:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        chains = self.current_slice.OptionChains

        contracts = []
        for chain in chains.Values:
            for contract in chain:
                expiration_date = contract.Expiry.date()

                if expiration_date < minimum_expiration:
                    continue

                if contract.Right != OptionRight.Call:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying SPY call contract.")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in contracts
        )

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiration
        ]

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))

        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        chain_contract = None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    chain_contract = contract
                    break
            if chain_contract is not None:
                break

        if chain_contract is None:
            return

        bid = chain_contract.BidPrice
        ask = chain_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        self._submit_exit("profit target")

    def _handle_expiration_processing(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if current_date >= expiry_date:
            self._submit_exit("expiration processing")
            return

        if (
            current_date == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order.")

        self.exit_ticket = self.MarketOrder(self.held_option, quantity)
        self.Debug(
            "Exit submitted: {} reason={}".format(
                self.held_option, reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} price={}".format(
                        self.held_option, self.entry_price
                    )
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if self.held_option is not None:
                self.Debug("Exit filled: {}".format(order_event.Symbol))

            if (
                self.held_option is not None
                and not self.Portfolio[self.held_option].Invested
            ):
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Invested:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating."
            )
            self.Liquidate(self.spy)

    def _is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )
