from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2021, 1, 1)
        self.SetEndDate(2023, 12, 31)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .CallsOnly()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal_time = None

        self.held_option = None
        self.entry_order = None
        self.entry_price = None
        self.exit_order = None
        self.expiration_date = None
        self.assignment_liquidation_order = None

    def OnFiveMinuteBar(self, sender, bar):
        if not self.fast.IsReady or not self.slow.IsReady:
            self.fast.Update(bar.EndTime, bar.Close)
            self.slow.Update(bar.EndTime, bar.Close)
            return

        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bar_time = bar.EndTime.time()
        if (
            previous_fast <= previous_slow
            and current_fast > current_slow
            and time(9, 45) <= bar_time <= time(14, 30)
        ):
            self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_option is not None:
            self.HandleExpirationProcessing()
            self.HandleOptionExits(slice)

        if self.pending_signal_time is not None:
            signal_time = self.pending_signal_time
            self.pending_signal_time = None

            if signal_time.date() == self.Time.date():
                self.TryEnter(slice)

        if self.spy in slice.Bars:
            bar = slice.Bars[self.spy]
            if (
                bar.EndTime.time() >= time(9, 31)
                and bar.EndTime.time() <= time(16, 0)
            ):
                self.consolidator.Update(bar)

    def TryEnter(self, slice):
        if self.held_option is not None:
            return

        if self.entry_order is not None and not self.entry_order.Status.IsClosed():
            return

        if self.option.Symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        minimum_expiration = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        selected_expiration = expirations[0]
        current_price = self.Securities[self.spy].Price
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = candidates[0]

        self.entry_order = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"Entry submitted: {contract.Symbol} "
            f"expiration={selected_expiration} strike={contract.Strike}"
        )

    def HandleOptionExits(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        if symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]
            bid = quote.Bid.Close
            ask = quote.Ask.Close

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * self.entry_price:
                    self.SubmitExit("profit target")

    def HandleExpirationProcessing(self):
        if self.held_option is None or self.expiration_date is None:
            return

        today = self.Time.date()

        if today >= self.expiration_date:
            self.SubmitExit("expiration processing")

        elif self.Time.time() >= time(15, 45):
            previous_trading_day = self.PreviousTradingDay(self.expiration_date)
            if today == previous_trading_day:
                self.SubmitExit("expiration time stop")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        symbol = self.held_option
        quantity = self.Portfolio[symbol].Quantity

        if quantity == 0:
            return

        if self.exit_order is not None and not self.exit_order.Status.IsClosed():
            return

        self.exit_order = self.MarketOrder(symbol, -quantity)
        self.Debug(f"Exit submitted: {symbol} reason={reason}")

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity

            if (
                self.assignment_liquidation_order is None
                or self.assignment_liquidation_order.Status.IsClosed()
            ):
                self.Debug(
                    f"Unexpected SPY equity position detected; "
                    f"liquidating quantity={quantity}."
                )
                self.assignment_liquidation_order = self.MarketOrder(
                    self.spy, -quantity
                )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self.entry_order is not None and order_event.OrderId == self.entry_order.OrderId:
            if self.held_option is None and order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()

                self.Debug(
                    f"Entry filled: {self.held_option} "
                    f"price={self.entry_price}"
                )

                self.entry_order = None

        elif self.exit_order is not None and order_event.OrderId == self.exit_order.OrderId:
            if order_event.FillQuantity != 0:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )

                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_option = None
                    self.entry_price = None
                    self.expiration_date = None
                    self.exit_order = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(f"Unexpected exercise or assignment: {assignment_event}")
